SELECT orders.status, DATE_TRUNC('MONTH', orders.order_date) AS order_month, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(payments.status))) AS status_values, ROUND((100 * SUM(CASE WHEN payments.method = 'cash' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_cash FROM payments LEFT JOIN orders ON orders.id = payments.order_id JOIN stores ON stores.id = orders.store_id WHERE UPPER(stores.store_name) LIKE '%IVE%' GROUP BY orders.status, DATE_TRUNC('MONTH', orders.order_date);
